    let a = rounded_f64(a, 41)?;
    let my = rounded_f64(my, 41)?;
    let along_2 = a * my;
    let along = along_1 - along_2;
    let across_1 = a * mx;
    let across_2 = b * my;
    let across = across_1 + across_2;
    let d = rounded_f64(d, 82)?;
    let k_x = exact_f64(k.x);
    let h_1 = a * k_x;
    let h_2 = d - h_1;
    let k_y = exact_f64(k.y);
    let h_3 = b * k_y;
    let h = h_2 - h_3;
    let p = rounded_f64(p, 22)?;
    let pa = p * along;
    let q = rounded_f64(q, 22)?;
    let qa = q * across;
    let qh = q * h;
    let s_1 = pa * pa;
    let s_2 = qa * qa;
    let s_3 = s_1 + s_2;
    let s_4 = qh * qh;
    let s = s_3 - s_4;
    let m_x = largest_magnitude([k_x]);
    let m_y = largest_magnitude([k_y]);
    let m_n = largest_magnitude([b, a]);
    let m_d = largest_magnitude([d]);
    let m_m = largest_magnitude([mx, my]);
    let m_r = largest_magnitude([p, q]);
    let scale = larger(m_d * m_d, m_n * m_n * m_m * m_m);
    let scale = larger(scale, m_y * m_n * m_d);
    let scale = larger(scale, m_y * m_y * m_n * m_n);
    let scale = larger(scale, m_x * m_n * m_d);
    let scale = larger(scale, m_x * m_y * m_n * m_n);
    let scale = larger(scale, m_x * m_x * m_n * m_n);
    let scale = m_r * m_r * scale;
