    let h_1 = i128::from(a).checked_mul(i128::from(k_x))?;
    let h_2 = d.checked_sub(h_1)?;
    let k_y = k.y.get();
    let h_3 = i128::from(b).checked_mul(i128::from(k_y))?;
    let h = h_2.checked_sub(h_3)?;
    let p = i64::try_from(within(p, 22)?).ok()?;
    let pa = i128::from(p).checked_mul(along)?;
    let q = i64::try_from(within(q, 22)?).ok()?;
    let qa = i128::from(q).checked_mul(across)?;
    let qh = i128::from(q).checked_mul(h)?;
